from dataclasses import dataclass
@dataclass(frozen=True, slots=True, repr=False)
class Some:
    _0: object
    def __repr__(self):
        return f"Some({self._0!r})"
@dataclass(frozen=True, slots=True, repr=False)
class None_:
    def __repr__(self):
        return "None_"
_None_ = None_()
def _pf_min_by(f, xs):
    return Some(min(xs, key=f)) if xs else _None_
byNeg = _pf_min_by(lambda x: 0 - x, [3, 1, 2])
none = _pf_min_by(lambda x: x, [])
pick = _pf_min_by
print(byNeg)
print(none)
print(pick(lambda s: len(s), ["ccc", "a", "bb"]))
